function CameraCorrida() {
    const { camera } = useThree();
    useEffect(() => {
        camera.position.set(0, 6.1, 13.0);
        camera.lookAt(0, 1.45, -14.5);
        camera.updateProjectionMatrix();
    }, [camera]);
    return null;
}
function PetalaFormato({ pos, escala, angulo = 0, cor, brilho = false, }) {
    return (<mesh position={pos} rotation={[0, 0, angulo]} scale={escala}>
      <sphereGeometry args={[1, 12, 9]}/>
      <meshStandardMaterial color={cor} roughness={0.8} emissive={brilho ? cor : '#000000'} emissiveIntensity={brilho ? 0.24 : 0}/>
    </mesh>);
}
function Coroa({ quantidade, raio, comprimento, largura, cor, z = 0, deslocamento = 0, espessura = 0.06, brilho = false, }) {
    return (<group>
      {Array.from({ length: quantidade }, (_, i) => {
            const a = 2 * Math.PI * i / quantidade + deslocamento;
            return (<PetalaFormato key={i} pos={[Math.sin(a) * raio, Math.cos(a) * raio, z]} escala={[largura, comprimento, espessura]} angulo={-a} cor={cor} brilho={brilho}/>);
        })}
    </group>);
}
