function PisoDecoradoMundo({ fase, indice }) {
    const mundo = visualFase(fase);
    const tipo = mundo.tipo;
    const brilho = tipo === 'lunar' || tipo === 'cristais' || tipo === 'celestial';
    const pedra = tipo === 'cerejeiras' ? '#F2E0D9' : tipo === 'bosque' ? '#A7BE9D' :
        tipo === 'doces' ? '#FFE8E3' : tipo === 'aquatico' ? '#BCEBE5' :
            tipo === 'cristais' ? '#D8CBF8' : tipo === 'poente' ? '#ECD2A1' :
                tipo === 'lunar' ? '#7185B2' : tipo === 'fenix' ? '#A86756' :
                    tipo === 'arcoiris' ? '#F8E5F6' : '#F0E9D8';
    return <group>
    {[-1, 0, 1].map((faixa, i) => <mesh key={i} position={[faixa * 2.3, 0, 0]} rotation={[-Math.PI / 2, 0, 0]}>
      <planeGeometry args={[2.06, 4.4]}/>
      <meshStandardMaterial color={pedra} transparent opacity={indice % 2 === 0 ? 0.40 : 0.26} roughness={0.9}/>
    </mesh>)}
    {tipo === 'cristais' || tipo === 'lunar' ? [-1, 1].map(l => <mesh key={l} position={[l * 2.9, .02, 0]} rotation={[-Math.PI / 2, 0, 0]}>
      <circleGeometry args={[.15, 6]}/>
      <meshBasicMaterial color={brilho ? '#D8E8FF' : '#FFFFFF'}/>
    </mesh>) : null}
    {tipo === 'doces' && [-1, 1].map((l, i) => <mesh key={l} position={[l * 3.11, .02, 0]} rotation={[-Math.PI / 2, 0, 0]}>
      <torusGeometry args={[.22, .07, 8, 20]}/><meshBasicMaterial color={i === 0 ? '#ED94BA' : '#8FCEDF'}/>
    </mesh>)}
    {tipo === 'cerejeiras' && [-1, 1].map(l => <mesh key={l} position={[l * 2.9, .015, 0]} rotation={[-Math.PI / 2, 0, l * .5]}>
      <circleGeometry args={[.12, 5]}/><meshBasicMaterial color="#EE9BC4"/>
    </mesh>)}
  </group>;
}
