                    setMoedasJardim(numero(j.moedas));
                    setGenero(j.personagem === 'masculino' ? 'masculino' : 'feminino');
                    if (Array.isArray(j.desbloqueadas)) {
                        const ok = j.desbloqueadas.filter((n) => typeof n === 'number' &&
                            Number.isInteger(n) &&
                            n >= 0 &&
                            n < plantasCatalogo.length);
                        setDesbloqueadas(Array.from(new Set([0, ...ok])));
                    }
                    if (Array.isArray(j.plantas)) {
                        setPlantas(Array.from({ length: MAX_CANTEIROS }, (_, idx) => {
                            const p = j.plantas[idx];
                            if (!p ||
                                !Number.isInteger(p.especie) ||
                                p.especie < 0 ||
                                p.especie >= plantasCatalogo.length) {
                                return null;
                            }
                            return {
                                id: numero(p.id) || Date.now() + idx,
                                especie: p.especie,
                                fase: saturar(numero(p.fase), 0, 2),
                                regada: !!p.regada,
                            };
                        }));
                    }
                    setAbertos(saturar(numero(j.canteirosDesbloqueados) || 6, 6, MAX_CANTEIROS));
                    setEspecieAtiva(saturar(numero(j.especieAtiva), 0, plantasCatalogo.length - 1));
                    setNivelRegador(saturar(numero(j.nivelRegador) || 1, 1, 3));
                    setNivelFerramentas(saturar(numero(j.nivelFerramentas) || 1, 1, 3));
                    setExperiencia(numero(j.experiencia));
